def run_pty(args, inputs, rows=24, cols=80, wait=0.5, env=None):
    # use script? use pty module fork
    import pty, os, select, time, errno
    pid, fd = pty.fork()
    if pid==0:
        os.environ["TERM"]="xterm-256color"
        if env:
            os.environ.update(env)
        # set winsize via ioctl after fork? child inherits? We'll set in parent before? use stty?
        os.execv(args[0], args)
    else:
