import subprocess, time, os
EXE="/workspace/executable"
WORK="/tmp/testwork"
def start(sess="t1", args=[], w=80, h=24, env=None, cwd=None, exe=None):
    subprocess.run(["tmux","kill-session","-t",sess], capture_output=True)
    work=cwd or WORK
    os.makedirs(work, exist_ok=True)
    cmd = f"cd {work} && {exe or EXE} {' '.join(args)}"
    e=dict(os.environ)
    if env: e.update(env)
    subprocess.run(["tmux","new-session","-d","-s",sess,"-x",str(w),"-y",str(h), cmd], env=e)
    time.sleep(0.4)
def cap(sess="t1", esc=False):
    a=["tmux","capture-pane","-t",sess,"-p"]
    if esc: a.append("-e")
    return subprocess.run(a, capture_output=True, text=True).stdout
def lines(sess="t1"):
    return cap(sess).split("\n")
def status(sess="t1"):
    ls=lines(sess)
    return ls[ -3 if False else 22] if len(ls)>22 else ""
def show(sess="t1", esc=False):
    txt=cap(sess,esc)
    for i,l in enumerate(txt.split("\n")):
        print(f"{i+1:2d}|{l}|")
    print("cursor", cursor(sess))
def cursor(sess="t1"):
    return subprocess.run(["tmux","display-message","-t",sess,"-p","#{cursor_x},#{cursor_y}"], capture_output=True, text=True).stdout.strip()
def send(sess,*ks, delay=0.07):
    if ks:
        subprocess.run(["tmux","send-keys","-t",sess]+list(ks)); time.sleep(delay)
def sendlit(sess, txt, delay=0.07):
    subprocess.run(["tmux","send-keys","-t",sess,"-l",txt]); time.sleep(delay)
def kill(sess="t1"):
    subprocess.run(["tmux","kill-session","-t",sess], capture_output=True)
def stat(sess="t1"):
    ls=lines(sess)
    # find status by search? Standard 24h: index22, but after open bug may shift; use second last non?
    return (cursor(sess), ls[22].strip() if len(ls)>22 else "", ls[23] if len(ls)>23 else "")
