SYNTAX_BY_EXT = {}
for _syn in SYNTAXES:
    for _ext in _syn.extensions:
        SYNTAX_BY_EXT[_ext] = _syn


def syntax_for_filename(filename):
    if filename is None:
        return PLAIN
    base = filename.replace('\\', '/').rsplit('/', 1)[-1]
    # Rust Path::extension(): a leading-dot name such as ".rs" has no ext.
    if base.startswith('.') and base.count('.') == 1:
        return PLAIN
    if '.' not in base:
        return PLAIN
    ext = base.rsplit('.', 1)[1]
    if ext == '':
        return PLAIN
    return SYNTAX_BY_EXT.get(ext, PLAIN)


# ------------------------------------------------------------- text buffer

class Change:
    __slots__ = ('before_rows', 'before_cursor', 'after_rows', 'after_cursor')

    def __init__(self, before_rows, before_cursor, after_rows, after_cursor):
        self.before_rows = before_rows
        self.before_cursor = before_cursor
        self.after_rows = after_rows
        self.after_cursor = after_cursor


class Buffer:
    def __init__(self, filename, rows):
        self.filename = filename
        self.rows = list(rows)
        self.cx = 0
        self.cy = 0
        self.row_offset = 0
        self.col_offset = 0
        self.syntax = syntax_for_filename(filename)
        self.history = []
        self.hindex = 0
        self.saved_index = 0
        self.dirty = False
        self.can_extend = False
        # syntax highlight cache
        self._hl = []          # per-row list of categories
        self._hl_state = [None]  # state at start of each row (+ sentinel)
        self._hl_dirty_from = 0

    # ---- row helpers -------------------------------------------------
    def row_len(self, y=None):
        if y is None:
            y = self.cy
        if 0 <= y < len(self.rows):
            return len(self.rows[y])
        return 0

    def cur_row(self):
        if 0 <= self.cy < len(self.rows):
            return self.rows[self.cy]
        return ''

    # ---- syntax ------------------------------------------------------
    def invalidate_syntax(self, from_row):
        if from_row is None:
            return
        if from_row < self._hl_dirty_from:
            self._hl_dirty_from = from_row
        # drop cached rows from that point
        if from_row < len(self._hl):
            del self._hl[from_row:]
            del self._hl_state[from_row + 1:]

    def highlights_upto(self, upto):
        """Ensure highlights are computed for rows < upto."""
        if self.syntax is PLAIN:
            return
        if upto > len(self.rows):
            upto = len(self.rows)
        while len(self._hl) < upto:
            y = len(self._hl)
            state = self._hl_state[y]
            hl, new_state = scan_row_syntax(self.rows[y], self.syntax, state)
            self._hl.append(hl)
            self._hl_state.append(new_state)

    def row_highlights(self, y):
        if self.syntax is PLAIN:
            return None
        self.highlights_upto(y + 1)
        if y < len(self._hl):
            return self._hl[y]
        return None


def scan_number(row, i, syntax):
    """Return end index of the number token starting at i."""
    n = len(row)
    adv = syntax.number_advanced
    # radix prefixes
    if row[i] == '0' and i + 2 < n + 1 and i + 1 < n:
        prefix = row[i + 1]
        if adv and prefix == 'x' and i + 2 < n and (
                row[i + 2] in '0123456789abcdefABCDEF_'):
            j = i + 2
            while j < n and row[j] in '0123456789abcdefABCDEF_':
                j += 1
            return j
        if adv and prefix == 'b' and i + 2 < n and row[i + 2] in '01_':
            j = i + 2
            while j < n and row[j] in '01_':
                j += 1
            return j
        if not adv and prefix == 'x' and i + 2 < n and (
                row[i + 2] in '0123456789abcdefABCDEF'):
            j = i + 2
            while j < n and row[j] in '0123456789abcdefABCDEF':
                j += 1
            return j
    j = i
    if adv:
        while j < n and (row[j].isdigit() or row[j] == '_'):
            j += 1
        while j < n and row[j] == '.':
            j += 1
            while j < n and (row[j].isdigit() or row[j] == '_'):
                j += 1
    else:
        while j < n and row[j].isdigit():
            j += 1
        while j < n and row[j] == '.':
            j += 1
            while j < n and row[j].isdigit():
                j += 1
    return j


def scan_row_syntax(row, syntax, state):
    """Scan one row.  state is None, ('block',) or ('string', quote).

    Returns (highlights list, outgoing state)."""
    n = len(row)
    hl = [HL_NORMAL] * n
    if syntax is PLAIN:
        return hl, None
    name_pending = False
    i = 0
    while i < n:
        if state is not None and state[0] == 'block':
            end = row.find('*/', i)
            if end == -1:
                for k in range(i, n):
                    hl[k] = HL_COMMENT
                i = n
            else:
                for k in range(i, end + 2):
                    hl[k] = HL_COMMENT
                i = end + 2
                state = None
            name_pending = False
            continue
        if state is not None and state[0] == 'string':
            quote = state[1]
            hl[i] = HL_STRING
            if row[i] == quote and not (i > 0 and row[i - 1] == '\\'):
                state = None
            i += 1
            name_pending = False
            continue
        ch = row[i]
        # comments
        if syntax.line_comment and row.startswith(syntax.line_comment, i):
            for k in range(i, n):
                hl[k] = HL_COMMENT
            i = n
            name_pending = False
            continue
        if syntax.block_comment and row.startswith('/*', i):
            state = ('block',)
            continue
        # strings
        if ch in syntax.string_delims or (syntax.backtick and ch == '`'):
            state = ('string', ch)
            continue
        # char literals in C-like languages
        if syntax.char_literal and ch == "'":
            matched = 0
            if i + 3 < n + 1 and i + 3 <= n - 1 and row[i + 1] == '\\' and \
                    row[i + 3] == "'":
                matched = 4
            elif i + 2 <= n - 1 and row[i + 2] == "'":
                matched = 3
            if matched:
                for k in range(i, i + matched):
                    hl[k] = HL_STRING
                i += matched
            else:
                hl[i] = HL_NORMAL
                i += 1
            name_pending = False
            continue
        if ch.isspace():
            i += 1
            continue
        if ch.isdigit() and ch.isascii():
            j = scan_number(row, i, syntax)
            cat = HL_NAME if name_pending else HL_LITERAL
            for k in range(i, j):
                hl[k] = cat
            i = j
            continue
        if is_word_char(ch):
            j = i
            while j < n and is_word_char(row[j]):
                j += 1
            word = row[i:j]
            cat = syntax.categories.get(word)
            if cat is None:
                cat = HL_NAME if name_pending else HL_NORMAL
            for k in range(i, j):
                hl[k] = cat
            if word in syntax.triggers:
                name_pending = True
            i = j
            continue
        # punctuation / operators
        name_pending = False
        i += 1
    return hl, state


def split_rust_lines(text):
    rows = []
    start = 0
    n = len(text)
    while start < n:
        idx = text.find('\n', start)
        if idx == -1:
            rows.append(text[start:])
            break
        line = text[start:idx]
        if line.endswith('\r'):
            line = line[:-1]
        rows.append(line)
        start = idx + 1
    return rows


def validate_rows(rows):
    for row in rows:
        for ch in row:
            if unicodedata.category(ch) == 'Cc' and ch not in ('\t', '\0'):
                raise FatalError(
                    'Invalid character for text is included: %s'
                    % rust_char_debug(ch))


def load_buffer_from_file(path):
    try:
        with open(path, 'rb') as fh:
            data = fh.read()
    except FileNotFoundError:
        return Buffer(path, [''])
    except IsADirectoryError as exc:
        raise FatalError(format_os_error(exc))
    except PermissionError as exc:
        raise FatalError(format_os_error(exc))
    except OSError as exc:
        raise FatalError(format_os_error(exc))
    try:
        text = data.decode('utf-8')
    except UnicodeDecodeError:
        raise FatalError('stream did not contain valid UTF-8')
    rows = split_rust_lines(text)
    validate_rows(rows)
    return Buffer(path, rows)


def buffer_content_bytes(buf):
    if not buf.rows:
        return b''
    return ''.join(row + '\n' for row in buf.rows).encode('utf-8')


# ------------------------------------------------------------- input seqs

class Seq:
    __slots__ = ('kind', 'value', 'mod')

    def __init__(self, kind, value=None, mod=None):
        self.kind = kind
        self.value = value
        self.mod = mod

    def __repr__(self):
        return 'Seq(%r,%r,%r)' % (self.kind, self.value, self.mod)


EOF_SEQ = Seq('eof')

_PANIC_CSI_FINALS = set('JKcfghlmnqty')


class InputParser:
    def __init__(self):
        self.buf = bytearray()
        self.pos = 0
        self.eof = False

    def _fill(self):
        if self.eof:
            return False
        try:
            data = os.read(0, 65536)
        except OSError:
            self.eof = True
            return False
        if not data:
            self.eof = True
            return False
        if self.pos:
            del self.buf[:self.pos]
            self.pos = 0
        self.buf.extend(data)
        return True

    def get_byte(self):
        while self.pos >= len(self.buf):
            if not self._fill():
                return None
        b = self.buf[self.pos]
        self.pos += 1
        return b

    # ---- utf8 decoding ------------------------------------------------
    def decode_char(self, first):
        """Decode a char starting with byte `first` (>=0x80 or printable)."""
        data = bytearray([first])
        if first < 0x80:
            return chr(first)
        # collect until valid, incomplete or 4 bytes
        while True:
            try:
                return bytes(data).decode('utf-8')
            except UnicodeDecodeError as exc:
                if len(data) >= 4:
                    raise self._non_utf8_error(data)
                # if the sequence is definitively invalid we still collect
                # up to four bytes, mirroring the observed behaviour
                nxt = self.get_byte()
                if nxt is None:
                    raise self._non_utf8_error(data)
                data.append(nxt)

    def _non_utf8_error(self, data):
        seq = ''.join('\\x%02x' % b for b in data)
        return InputSequenceError(
            'Cannot handle non-UTF8 multi-byte input sequence: %s' % seq)

    # ---- main ----------------------------------------------------------
    def next_seq(self):
        while True:
            seq = self._next_seq_inner()
            if seq is not None:
                return seq
            # None means a discarded escape sequence; keep reading

    def _next_seq_inner(self):
        b = self.get_byte()
        if b is None:
            return EOF_SEQ
        if b == 0x1b:
            return self._escape()
        if b < 0x80:
            return self._byte_seq(b)
        ch = self.decode_char(b)
        return Seq('char', ch)

    def _byte_seq(self, b):
        if b == 0x7f:
            return Seq('char', '\x7f')
        if b < 0x20:
            return Seq('ctrl', b)
        return Seq('char', chr(b))

    def _escape(self):
        b2 = self.get_byte()
        if b2 is None:
            return EOF_SEQ
        if b2 == 0x5b:  # [
            return self._csi()
        if b2 == 0x1b or b2 < 0x20 or b2 == 0x7f:
            return Seq('esc')
        # Alt + character
        if b2 < 0x80:
            ch = chr(b2)
        else:
            ch = self.decode_char(b2)
        return Seq('alt', ch)

    def _csi(self):
        params = bytearray()
        while True:
            b = self.get_byte()
            if b is None:
                return EOF_SEQ
            if 0x40 <= b <= 0x7e:
                final = chr(b)
                break
            params.append(b)
        pstr = params.decode('ascii', 'ignore')
        # mouse-like sequences are simply discarded below
        if final in 'ABCDHF':
            # split parameters
            parts = pstr.split(';')
            mod = None
            if len(parts) >= 2 and parts[1] == '5':
                mod = 'ctrl'
            names = {'A': 'up', 'B': 'down', 'C': 'right', 'D': 'left',
                     'H': 'home', 'F': 'end'}
            name = names[final]
            if mod == 'ctrl' and name in ('home', 'end'):
                return Seq('ctrlkey', name)
            return Seq('key', name, mod)
        if final == '~':
            parts = pstr.split(';')
            try:
                num = int(parts[0]) if parts and parts[0] else 0
            except ValueError:
                return None
            mapping = {1: 'home', 7: 'home', 3: 'delete', 4: 'end',
                       8: 'end', 5: 'pageup', 6: 'pagedown'}
            name = mapping.get(num)
            if name is None:
                return None
            return Seq('key', name)
        if final == 'Z':
            return None
        if final in _PANIC_CSI_FINALS:
            raise EditorPanic('src/input.rs:254:18',
                              'internal error: entered unreachable code')
        return None


def seq_display(seq):
    """Display form used in `Key '...' not mapped` messages."""
    if seq.kind == 'ctrl':
        code = seq.value
        if code == 0:
            return 'C-SPACE'
        if 1 <= code <= 26:
            return 'C-' + chr(code + 96)
        if code == 28:
            return 'C-\\'
        if code == 29:
            return 'C-]'
        if code == 30:
            return 'C-~'
        if code == 31:
            return 'C-?'
        return 'C-' + chr(code + 64)
    if seq.kind == 'alt':
        return 'M-' + seq.value
    if seq.kind == 'ctrlkey':
        return 'C-' + seq.value.upper()
    if seq.kind == 'char':
        return seq.value
    if seq.kind == 'esc':
        return 'ESC'
    if seq.kind == 'key':
        return seq.value.upper()
    return '?'


# ---------------------------------------------------------------- prompts

class Prompt:
    def __init__(self, kind):
        self.kind = kind  # 'save', 'open', 'search'
        self.text = ''
        # search state
        self.saved_cursor = None
        self.direction = 1

    def message_text(self):
        if self.kind == 'save':
            return 'Save as: %s (^G or ESC to cancel)' % self.text
        if self.kind == 'open':
            return ('Open: %s (Empty name for new text buffer, '
                    '^G or ESC to cancel)' % self.text)
        return ('Search: %s (^F or ^N or RIGHT to forward, '
                '^B or ^P or LEFT to back, ^G or ESC to cancel)' % self.text)

    def label_len(self):
        return {'save': 9, 'open': 6, 'search': 8}[self.kind]


# ----------------------------------------------------------------- editor

class RenderCtx:
    def __init__(self):
        self.content_from = None  # row index, 'all', or None
        self.status = False
        self.message = False
        self.cursor = False

    def all(self):
        self.content_from = 'all'
        self.status = True
        self.message = True


class Editor:
    def __init__(self, buffers, term):
        self.buffers = buffers
        self.cur = 0
        self.term = term
        self.message = 'Ctrl-? for help'
        self.message_alert = False
        self.prompt = None
        self.help_active = False
        self.warn_armed = False
        self.screen_rows = max(1, term.rows - 2)
        self._last_cursor_screen = None
        self._first_render = True
        self._show_welcome = len(buffers) == 1 and buffers[0].filename is None
        self.exited = False

    # -- helpers ---------------------------------------------------------
    @property
    def buf(self):
        return self.buffers[self.cur]

    def set_message(self, text, alert=False, ctx=None):
        self.message = text
        self.message_alert = alert
        if ctx is not None:
            ctx.message = True

    def effective_rows(self):
        if self.prompt is not None:
            return max(1, self.term.rows - 2)
        if self.message == '':
            return max(1, self.term.rows - 1)
        return max(1, self.term.rows - 2)

    # -- cursor geometry --------------------------------------------------
    def cursor_rx(self, buf):
        if buf.cy >= len(buf.rows):
            return 0
        row = buf.rows[buf.cy]
        cx = min(buf.cx, len(row))
        rx = 0
        for ch in row[:cx]:
            if ch == '\t':
                rx += 8 - (rx % 8)
            else:
                rx += char_width(ch)
        return rx

    def ensure_visible(self, buf):
        rows = self.screen_rows
        if buf.cy < buf.row_offset:
            buf.row_offset = buf.cy
        if buf.cy >= buf.row_offset + rows:
            buf.row_offset = buf.cy - rows + 1
        rx = self.cursor_rx(buf)
        cols = self.term.cols
        if rx < buf.col_offset:
            buf.col_offset = rx
        if rx >= buf.col_offset + cols:
            buf.col_offset = rx - cols + 1
            # align to a character boundary on the cursor row
            if buf.cy < len(buf.rows):
                row = buf.rows[buf.cy]
                pos = 0
                for ch in row:
                    w = 8 - (pos % 8) if ch == '\t' else char_width(ch)
                    if pos < buf.col_offset < pos + w:
                        buf.col_offset = pos + w
                        break
                    pos += w
        if buf.row_offset < 0:
            buf.row_offset = 0
        if buf.col_offset < 0:
            buf.col_offset = 0

    # -- terminal size ------------------------------------------------------
    def check_terminal_size(self):
        new_cols, new_rows = self.term.query_size_soft()
        if (new_cols, new_rows) != (self.term.cols, self.term.rows):
            self.term.cols = new_cols
            self.term.rows = new_rows
            if new_cols < 1 or new_rows < 3:
                raise FatalError(
                    'Screen %dx%d is too small. At least 1x3 is necessary '
                    'in width x height' % (new_cols, new_rows))
            # a resize clears the current message
            if self.prompt is None:
                self.message = ''
                self.message_alert = False
            self.screen_rows = self.effective_rows()
            return True
        if new_cols < 1 or new_rows < 3:
            raise FatalError(
                'Screen %dx%d is too small. At least 1x3 is necessary '
                'in width x height' % (new_cols, new_rows))
        return False

    # ------------------------------------------------------------ main loop
    def run(self, parser):
        self.render_initial()
        while not self.exited:
            seq = parser.next_seq()
            if seq.kind == 'eof':
                break
            self.handle(seq)
        return 0

    def handle(self, seq):
        resized = self.check_terminal_size()
        ctx = RenderCtx()
        if resized:
            ctx.all()
        if self.help_active:
            # any key dismisses the help screen
            self.help_active = False
            if not (seq.kind == 'ctrl' and seq.value == 17):
                self.warn_armed = False
            ctx.all()
            self.render(ctx)
            return
        if self.prompt is not None:
            self.handle_prompt(seq, ctx)
            if self.exited:
                return
            self.render(ctx)
            return
        # normal mode: any non-Ctrl-Q key clears the quit warning arming
        if not (seq.kind == 'ctrl' and seq.value == 17):
            self.warn_armed = False
        self.handle_normal(seq, ctx)
        if self.exited:
            return
        self.render(ctx)

    # ------------------------------------------------------------- movement
    def move_left(self, buf):
        if buf.cx > 0:
            buf.cx -= 1
        elif buf.cy > 0:
            buf.cy -= 1
            buf.cx = buf.row_len()

    def move_right(self, buf):
        if buf.cy < len(buf.rows):
            if buf.cx < buf.row_len():
                buf.cx += 1
            elif buf.cy < len(buf.rows):
                buf.cy += 1
                buf.cx = 0

    def move_up(self, buf):
        if buf.cy > 0:
            buf.cy -= 1
            buf.cx = min(buf.cx, buf.row_len())

    def move_down(self, buf):
        if buf.cy < len(buf.rows):
            buf.cy += 1
            buf.cx = min(buf.cx, buf.row_len())

    # word movement over the whole buffer (a newline is a non-word char)
    def _char_at(self, buf, cy, cx):
        if cy < len(buf.rows):
            row = buf.rows[cy]
            if cx < len(row):
                return row[cx]
            return '\n'
        return None

    def move_next_word(self, buf):
        if buf.cy >= len(buf.rows):
            return
        self.move_right(buf)
        ch = self._char_at(buf, buf.cy, buf.cx)
        if ch is None:
            return
        if is_word_char(ch):
            while True:
                ch = self._char_at(buf, buf.cy, buf.cx)
                if ch is None or not is_word_char(ch):
                    break
                self.move_right(buf)
            while True:
                ch = self._char_at(buf, buf.cy, buf.cx)
                if ch is None or not (ch == '\n' or ch.isspace()):
                    break
                self.move_right(buf)
        else:
            while True:
                ch = self._char_at(buf, buf.cy, buf.cx)
                if ch is None or is_word_char(ch):
                    break
                self.move_right(buf)

    def move_prev_word(self, buf):
        if buf.cy == 0 and buf.cx == 0:
            return
        self.move_left(buf)
        ch = self._char_at(buf, buf.cy, buf.cx)

        def prev_char():
            if buf.cx > 0:
                return buf.rows[buf.cy][buf.cx - 1]
            if buf.cy > 0:
                return '\n'
            return None

        if ch is not None and is_word_char(ch):
            while True:
                pc = prev_char()
                if pc is None or not is_word_char(pc):
                    break
                self.move_left(buf)
        else:
            while True:
                ch = self._char_at(buf, buf.cy, buf.cx)
                if ch is None or is_word_char(ch):
                    break
                if buf.cy == 0 and buf.cx == 0:
                    break
                self.move_left(buf)
            while True:
                pc = prev_char()
                if pc is None or not is_word_char(pc):
                    break
                self.move_left(buf)

    def prev_word_in_line(self, buf):
        """Target column of a line-local previous-word move (for Ctrl-W)."""
        row = buf.cur_row()
        cx = buf.cx
        if cx <= 0:
            return 0
        cx -= 1
        if cx >= len(row):
            cx = len(row) - 1
            if cx < 0:
                return 0
        ch = row[cx] if 0 <= cx < len(row) else '\n'
        if is_word_char(ch):
            while cx > 0 and is_word_char(row[cx - 1]):
                cx -= 1
            return cx
        # skip non-word characters, then the word before them
        while cx >= 0:
            ch = row[cx] if cx < len(row) else None
            if ch is not None and is_word_char(ch):
                break
            if cx == 0:
                return 0
            cx -= 1
        while cx > 0 and is_word_char(row[cx - 1]):
            cx -= 1
        return cx

    def move_next_paragraph(self, buf):
        if buf.cy >= len(buf.rows):
            return
        # step down line by line (clamping the column as plain Down does)
        cy = buf.cy
        # move to the first empty line, then past empty lines
        while cy < len(buf.rows) and len(buf.rows[cy]) != 0:
            cy += 1
        while cy < len(buf.rows) and len(buf.rows[cy]) == 0:
            cy += 1
        while buf.cy < cy:
            self.move_down(buf)
        buf.cy = cy
        buf.cx = min(buf.cx, buf.row_len())

    def move_prev_paragraph(self, buf):
        if buf.cy == 0:
            return
        self.move_up(buf)
        while buf.cy > 0:
            prev = buf.rows[buf.cy - 1] if buf.cy - 1 < len(buf.rows) else ''
            if len(prev) == 0:
                break
            self.move_up(buf)

    # --------------------------------------------------------------- editing
    def _snapshot(self, buf):
        return (list(buf.rows), (buf.cx, buf.cy))

    def _begin_mutation(self, buf):
        return (list(buf.rows), (buf.cx, buf.cy))

    def _finish_mutation(self, buf, before, kind, ctx):
        before_rows, before_cursor = before
        if buf.rows == before_rows:
            return False
        first = first_diff_row(before_rows, buf.rows)
        if kind == 'command' or not buf.can_extend or buf.hindex == 0:
            del buf.history[buf.hindex:]
            buf.history.append(Change(before_rows, before_cursor,
                                      list(buf.rows), (buf.cx, buf.cy)))
            buf.hindex += 1
        else:
            seg = buf.history[buf.hindex - 1]
            seg.after_rows = list(buf.rows)
            seg.after_cursor = (buf.cx, buf.cy)
        buf.dirty = True
        buf.can_extend = True
        buf.invalidate_syntax(first if first is not None else 0)
        ctx.content_from = first if first is not None else 'all'
        ctx.status = True
        return True

    def insert_char(self, buf, ch, ctx):
        before = self._begin_mutation(buf)
        if buf.cy >= len(buf.rows):
            buf.rows.append(ch)
            buf.cx = 1
        else:
            row = buf.rows[buf.cy]
            buf.rows[buf.cy] = row[:buf.cx] + ch + row[buf.cx:]
            buf.cx += 1
        self._finish_mutation(buf, before, 'char', ctx)

    def insert_newline(self, buf, ctx):
        before = self._begin_mutation(buf)
        if buf.cy >= len(buf.rows):
            buf.rows.insert(buf.cy, '')
            # cursor stays on the freshly inserted row
        else:
            row = buf.rows[buf.cy]
            left, right = row[:buf.cx], row[buf.cx:]
            buf.rows[buf.cy] = left
            buf.rows.insert(buf.cy + 1, right)
            buf.cy += 1
            buf.cx = 0
        self._finish_mutation(buf, before, 'command', ctx)

    def delete_char_before(self, buf, ctx):
        before = self._begin_mutation(buf)
        if buf.cy < len(buf.rows) and buf.cx > 0:
            row = buf.rows[buf.cy]
            buf.rows[buf.cy] = row[:buf.cx - 1] + row[buf.cx:]
            buf.cx -= 1
        elif 0 < buf.cy < len(buf.rows) and buf.cx == 0:
            prev_len = len(buf.rows[buf.cy - 1])
            buf.rows[buf.cy - 1] += buf.rows[buf.cy]
            del buf.rows[buf.cy]
            buf.cy -= 1
            buf.cx = prev_len
        self._finish_mutation(buf, before, 'command', ctx)

    def delete_char_next(self, buf, ctx):
        before = self._begin_mutation(buf)
        if buf.cy < len(buf.rows):
            row = buf.rows[buf.cy]
            if buf.cx < len(row):
                buf.rows[buf.cy] = row[:buf.cx] + row[buf.cx + 1:]
            elif buf.cy < len(buf.rows) - 1:
                buf.rows[buf.cy] = row + buf.rows[buf.cy + 1]
                del buf.rows[buf.cy + 1]
        self._finish_mutation(buf, before, 'command', ctx)

    def delete_word(self, buf, ctx):
        before = self._begin_mutation(buf)
        if buf.cy < len(buf.rows) and buf.cx > 0:
            target = self.prev_word_in_line(buf)
            row = buf.rows[buf.cy]
            buf.rows[buf.cy] = row[:target] + row[buf.cx:]
            buf.cx = target
        self._finish_mutation(buf, before, 'command', ctx)

    def delete_until_head(self, buf, ctx):
        before = self._begin_mutation(buf)
        if buf.cy < len(buf.rows):
            if buf.cx > 0:
                row = buf.rows[buf.cy]
                buf.rows[buf.cy] = row[buf.cx:]
                buf.cx = 0
            elif buf.cy > 0:
                prev_len = len(buf.rows[buf.cy - 1])
                buf.rows[buf.cy - 1] += buf.rows[buf.cy]
                del buf.rows[buf.cy]
                buf.cy -= 1
                buf.cx = prev_len
        self._finish_mutation(buf, before, 'command', ctx)

    def delete_until_end(self, buf, ctx):
        before = self._begin_mutation(buf)
        if buf.cy < len(buf.rows):
            row = buf.rows[buf.cy]
            if buf.cx < len(row):
                buf.rows[buf.cy] = row[:buf.cx]
            elif buf.cy < len(buf.rows) - 1:
                buf.rows[buf.cy] = row + buf.rows[buf.cy + 1]
                del buf.rows[buf.cy + 1]
        self._finish_mutation(buf, before, 'command', ctx)

    # -------------------------------------------------------------- undo/redo
    def do_undo(self, buf, ctx):
        buf.can_extend = False
        if buf.hindex == 0:
            self.set_message('No older change', ctx=ctx)
            return
        buf.hindex -= 1
        seg = buf.history[buf.hindex]
        old_rows = buf.rows
        buf.rows = list(seg.before_rows)
        buf.cx, buf.cy = seg.before_cursor
        buf.dirty = (buf.hindex != buf.saved_index)
        first = first_diff_row(old_rows, buf.rows)
        buf.invalidate_syntax(first if first is not None else 0)
        ctx.content_from = 'all'
        ctx.status = True

    def do_redo(self, buf, ctx):
        buf.can_extend = False
        if buf.hindex >= len(buf.history):
            self.set_message('Buffer is already newest', ctx=ctx)
            return
        seg = buf.history[buf.hindex]
        old_rows = buf.rows
        buf.rows = list(seg.after_rows)
        buf.cx, buf.cy = seg.after_cursor
        buf.hindex += 1
        buf.dirty = (buf.hindex != buf.saved_index)
        first = first_diff_row(old_rows, buf.rows)
        buf.invalidate_syntax(first if first is not None else 0)
        ctx.content_from = 'all'
        ctx.status = True

    # ------------------------------------------------------------------ save
    def save_to(self, buf, filename, ctx):
        data = buffer_content_bytes(buf)
        try:
            with open(filename, 'wb') as fh:
                fh.write(data)
        except OSError as exc:
            self.set_message('Could not save: %s' % format_os_error(exc),
                             alert=True, ctx=ctx)
            return False
        old_syntax = buf.syntax
        buf.filename = filename
        buf.syntax = syntax_for_filename(filename)
        buf.saved_index = buf.hindex
        buf.dirty = False
        buf.can_extend = False
        self.set_message('%d bytes written to %s' % (len(data), filename),
                         ctx=ctx)
        ctx.status = True
        if buf.syntax is not old_syntax:
            buf._hl = []
            buf._hl_state = [None]
            buf.invalidate_syntax(0)
            ctx.content_from = 'all'
        return True

    def do_save(self, buf, ctx):
        if buf.filename is None:
            self.prompt = Prompt('save')
            ctx.message = True
            return
        self.save_to(buf, buf.filename, ctx)

    # ------------------------------------------------------------- searching
    def all_matches(self, buf, query):
        matches = []
        if not query:
            return matches
        for y, row in enumerate(buf.rows):
            start = 0
            while True:
                idx = row.find(query, start)
                if idx == -1:
                    break
                matches.append((y, idx))
                start = idx + 1
        return matches

    def search_step(self, buf, prompt, nav):
        """nav: None for a query edit, +1/-1 for navigation keys."""
        query = prompt.text
        if not query:
            return
        matches = self.all_matches(buf, query)
        if not matches:
            return
        cur = (buf.cy, buf.cx)
        chosen = None
        if nav is None:
            if prompt.direction > 0:
                for m in matches:
                    if m >= cur:
                        chosen = m
                        break
                if chosen is None:
                    chosen = matches[0]
            else:
                for m in reversed(matches):
                    if m < cur:
                        chosen = m
                        break
                if chosen is None:
                    chosen = matches[-1]
        elif nav > 0:
            for m in matches:
                if m > cur:
                    chosen = m
                    break
            if chosen is None:
                chosen = matches[0]
        else:
            for m in reversed(matches):
                if m < cur:
                    chosen = m
                    break
            if chosen is None:
                chosen = matches[-1]
        buf.cy, buf.cx = chosen

    # ---------------------------------------------------------------- prompt
    def prompt_delete_word_text(self, prompt):
        # build a tiny fake buffer to reuse the line-local logic
        class _T:
            pass
        # simpler: compute with the same algorithm on prompt.text
        text = prompt.text
        cx = len(text)
        if cx <= 0:
            return False
        target = _prev_word_target(text, cx)
        if target == cx:
            return False
        prompt.text = text[:target]
        return True

    def handle_prompt(self, seq, ctx):
        prompt = self.prompt
        buf = self.buf
        # cancel
        if seq.kind == 'esc' or (seq.kind == 'ctrl' and seq.value == 7):
            if prompt.kind == 'search':
                buf.cx, buf.cy = prompt.saved_cursor
            self.prompt = None
            self.set_message('Canceled', ctx=ctx)
            ctx.content_from = 'all'
            ctx.status = True
            return
        # confirm
        if seq.kind == 'ctrl' and seq.value == 13:
            self._prompt_enter(ctx)
            return
        # search navigation
        if prompt.kind == 'search':
            nav = None
            if seq.kind == 'ctrl' and seq.value in (6, 14):
                nav = 1
            elif seq.kind == 'ctrl' and seq.value in (2, 16):
                nav = -1
            elif seq.kind == 'key' and seq.value == 'right' and seq.mod is None:
                nav = 1
            elif seq.kind == 'key' and seq.value == 'left' and seq.mod is None:
                nav = -1
            if nav is not None:
                prompt.direction = nav
                old = (buf.cy, buf.cx)
                self.search_step(buf, prompt, nav)
                ctx.message = True
                ctx.content_from = 'all'
                if (buf.cy, buf.cx) != old:
                    ctx.status = True
                return
        # deletion keys
        is_del_char = (seq.kind == 'char' and seq.value == '\x7f')
        is_bspace = is_del_char or (seq.kind == 'ctrl' and seq.value == 8) or \
            (seq.kind == 'key' and seq.value == 'delete')
        if seq.kind == 'ctrl' and seq.value == 23:  # Ctrl-W
            if self.prompt_delete_word_text(prompt):
                ctx.message = True
                if prompt.kind == 'search':
                    self.search_step(buf, prompt, None)
                    ctx.content_from = 'all'
                    ctx.status = True
            return
        if is_bspace:
            if prompt.text:
                prompt.text = prompt.text[:-1]
                ctx.message = True
                if prompt.kind == 'search':
                    self.search_step(buf, prompt, None)
                    ctx.content_from = 'all'
                    ctx.status = True
            elif is_del_char:
                # DEL on an empty prompt is inserted as a character
                prompt.text += '\x7f'
                ctx.message = True
                if prompt.kind == 'search':
                    self.search_step(buf, prompt, None)
                    ctx.content_from = 'all'
                    ctx.status = True
            return
        # character insertion (plain and Alt- characters)
        if seq.kind in ('char', 'alt') and seq.value != '\x7f':
            prompt.text += seq.value
            ctx.message = True
            if prompt.kind == 'search':
                self.search_step(buf, prompt, None)
                ctx.content_from = 'all'
                ctx.status = True
            return
        # everything else is ignored inside a prompt

    def _prompt_enter(self, ctx):
        prompt = self.prompt
        buf = self.buf
        kind = prompt.kind
        text = prompt.text
        self.prompt = None
        if kind == 'save':
            if text == '':
                self.set_message('', ctx=ctx)
                ctx.status = True
                return
            self.save_to(buf, text, ctx)
            ctx.content_from = ctx.content_from or 'all' \
                if buf.syntax is not None else ctx.content_from
            return
        if kind == 'open':
            if text == '':
                new_buf = Buffer(None, [''])
            else:
                new_buf = load_buffer_from_file(text)  # may raise FatalError
            self.buffers.append(new_buf)
            self.cur = len(self.buffers) - 1
            self.set_message('', ctx=ctx)
            ctx.all()
            return
        # search
        if text == '':
            buf.cx, buf.cy = prompt.saved_cursor
            self.set_message('Canceled', ctx=ctx)
        elif self.all_matches(buf, text):
            self.set_message('Found', ctx=ctx)
        else:
            self.set_message('Not found', ctx=ctx)
        ctx.content_from = 'all'
        ctx.status = True

    # ------------------------------------------------------------ normal mode
    def handle_normal(self, seq, ctx):
        buf = self.buf
        code = seq.value if seq.kind == 'ctrl' else None

        # ---- control keys
        if seq.kind == 'ctrl':
            c = code
            if c == 17:  # Ctrl-Q
                self._quit(ctx)
                return
            if c == 19:  # Ctrl-S
                self.do_save(buf, ctx)
                return
            if c == 15:  # Ctrl-O
                self.prompt = Prompt('open')
                ctx.message = True
                return
            if c == 24:  # Ctrl-X next buffer
                self._next_buffer(1, ctx)
                return
            if c == 7:  # Ctrl-G search
                pr = Prompt('search')
                pr.saved_cursor = (buf.cx, buf.cy)
                self.prompt = pr
                ctx.message = True
                return
            if c == 31:  # Ctrl-? help
                self.show_help()
                return
            if c == 12:  # Ctrl-L refresh
                self.set_message('', ctx=ctx)
                ctx.all()
                return
            if c == 21:  # Ctrl-U undo
                self.do_undo(buf, ctx)
                return
            if c == 18:  # Ctrl-R redo
                self.do_redo(buf, ctx)
                return
            before = (buf.cx, buf.cy, buf.row_offset, buf.col_offset)
            if c == 16 or c == 14:  # up / down
                if c == 16:
                    self.move_up(buf)
                else:
                    self.move_down(buf)
                self._cursor_move_ctx(buf, before, ctx)
                return
            if c == 6:  # right
                self.move_right(buf)
                self._cursor_move_ctx(buf, before, ctx)
                return
            if c == 2:  # left
                self.move_left(buf)
                self._cursor_move_ctx(buf, before, ctx)
                return
            if c == 1:  # head of line
                buf.cx = 0
                self._cursor_move_ctx(buf, before, ctx)
                return
            if c == 5:  # end of line
                buf.cx = buf.row_len()
                self._cursor_move_ctx(buf, before, ctx)
                return
            if c == 22 or c == 29:  # Ctrl-V / Ctrl-] next page
                self._page(buf, 1)
                self._cursor_move_ctx(buf, before, ctx, page=True)
                return
            if c == 8:  # Ctrl-H backspace
                self.delete_char_before(buf, ctx)
                return
            if c == 4:  # Ctrl-D delete next
                self.delete_char_next(buf, ctx)
                return
            if c == 23:  # Ctrl-W
                self.delete_word(buf, ctx)
                return
            if c == 10:  # Ctrl-J
                self.delete_until_head(buf, ctx)
                return
            if c == 11:  # Ctrl-K
                self.delete_until_end(buf, ctx)
                return
            if c == 13:  # Ctrl-M newline
                self.insert_newline(buf, ctx)
                return
            if c == 9:  # Ctrl-I tab
                self.insert_char(buf, '\t', ctx)
                return
            # unmapped control key
            self.set_message("Key '%s' not mapped" % seq_display(seq),
                             alert=True, ctx=ctx)
            return

        if seq.kind == 'char':
            if seq.value == '\x7f':
                self.delete_char_before(buf, ctx)
            else:
                self.insert_char(buf, seq.value, ctx)
            return

        if seq.kind == 'esc':  # Ctrl-[ : previous page
            before = (buf.cx, buf.cy, buf.row_offset, buf.col_offset)
            self._page(buf, -1)
            self._cursor_move_ctx(buf, before, ctx, page=True)
            return

        if seq.kind == 'alt':
            ch = seq.value
            before = (buf.cx, buf.cy, buf.row_offset, buf.col_offset)
            if ch == 'x':
                self._next_buffer(-1, ctx)
                return
            if ch == 'f':
                self.move_next_word(buf)
                self._cursor_move_ctx(buf, before, ctx)
                return
            if ch == 'b':
                self.move_prev_word(buf)
                self._cursor_move_ctx(buf, before, ctx)
                return
            if ch == 'n':
                self.move_next_paragraph(buf)
                self._cursor_move_ctx(buf, before, ctx)
                return
            if ch == 'p':
                self.move_prev_paragraph(buf)
                self._cursor_move_ctx(buf, before, ctx)
                return
            if ch == 'v':
                self._page(buf, -1)
                self._cursor_move_ctx(buf, before, ctx, page=True)
                return
            if ch == '<':
                self._move_top(buf)
                self._cursor_move_ctx(buf, before, ctx)
                return
            if ch == '>':
                buf.cy = len(buf.rows)
                buf.cx = 0
                self._cursor_move_ctx(buf, before, ctx)
                return
            self.set_message("Key '%s' not mapped" % seq_display(seq),
                             alert=True, ctx=ctx)
            return

        if seq.kind == 'ctrlkey':
            self.set_message("Key '%s' not mapped" % seq_display(seq),
                             alert=True, ctx=ctx)
            return

        if seq.kind == 'key':
            before = (buf.cx, buf.cy, buf.row_offset, buf.col_offset)
            name = seq.value
            if seq.mod == 'ctrl':
                if name == 'right':
                    self.move_next_word(buf)
                elif name == 'left':
                    self.move_prev_word(buf)
                elif name == 'down':
                    self.move_next_paragraph(buf)
                elif name == 'up':
                    self.move_prev_paragraph(buf)
                self._cursor_move_ctx(buf, before, ctx)
                return
            if name == 'up':
                self.move_up(buf)
            elif name == 'down':
                self.move_down(buf)
            elif name == 'right':
                self.move_right(buf)
            elif name == 'left':
                self.move_left(buf)
            elif name == 'home':
                buf.cx = 0
            elif name == 'end':
                buf.cx = buf.row_len()
            elif name == 'delete':
                self.delete_char_next(buf, ctx)
                return
            elif name == 'pageup':
                self._page(buf, -1)
            elif name == 'pagedown':
                self._page(buf, 1)
            self._cursor_move_ctx(buf, before, ctx,
                                  page=name in ('pageup', 'pagedown'))
            return

    def _cursor_move_ctx(self, buf, before, ctx, page=False):
        after = (buf.cx, buf.cy, buf.row_offset, buf.col_offset)
        if before == after:
            # ensure_visible in render may still change offsets
            ctx.cursor = True
            return
        ctx.cursor = True
        if before[1] != buf.cy:
            ctx.status = True
        if page:
            ctx.status = True

    def _move_top(self, buf):
        buf.cy = 0
        # The original does not clamp the column and faults when it points
        # beyond the first row while computing the cursor position.
        if len(buf.rows) > 0 and buf.cx > len(buf.rows[0]):
            first = buf.rows[0]
            if any(ord(c) > 127 for c in first):
                raise EditorPanic(
                    'src/row.rs:51:25',
                    'index out of bounds: the len is %d but the index is %d'
                    % (len(first), buf.cx))
            raise EditorPanic(
                'src/row.rs:125:13',
                'byte index %d is out of bounds of `%s`' % (buf.cx, first))

    def _page(self, buf, direction):
        rows = self.screen_rows
        if direction > 0:
            buf.cy = min(buf.row_offset + rows - 1, len(buf.rows))
            for _ in range(rows):
                self.move_down(buf)
        else:
            buf.cy = buf.row_offset
            buf.cx = min(buf.cx, buf.row_len())
            for _ in range(rows):
                self.move_up(buf)

    def _next_buffer(self, delta, ctx):
        if len(self.buffers) <= 1:
            self.set_message('No other buffer is opened', ctx=ctx)
            return
        self.cur = (self.cur + delta) % len(self.buffers)
        ctx.all()

    def _quit(self, ctx):
        if any(b.dirty for b in self.buffers):
            if self.warn_armed:
                self.exited = True
                return
            self.warn_armed = True
            self.set_message(
                'At least one file has unsaved changes! Press ^Q again to '
                'quit or ^S to save', alert=True, ctx=ctx)
            return
        self.exited = True

    # ------------------------------------------------------------------ help
    def show_help(self):
        term = self.term
        rows = self.screen_rows
        cols = term.cols
        lines = ['%-30s: %s' % (k, d) for k, d in MAPPINGS]
        block_w = max(len(l) for l in lines)
        indent = max(0, (cols - block_w) // 2)
        top = 0
        if rows > len(lines):
            top = (rows - len(lines)) // 2
        out = []
        for i in range(rows):
            out.append('\x1b[%dH' % (i + 1))
            idx = i - top
            if 0 <= idx < len(lines):
                line = lines[idx]
                key_part, rest = line[:30], line[30:]
                text = ' ' * indent + key_part + rest
                # colour the key part
                seg = ' ' * indent
                out.append(term.esc_for(HL_SPECIAL, seg=''))
                out.append(seg)
                out.append(term.color_seq(HL_SPECIAL))
                out.append(key_part)
                out.append(term.color_seq(HL_NORMAL))
                out.append(rest)
                out.append('\x1b[K')
            else:
                out.append('\x1b[K')
        term.write(''.join(out).encode('utf-8', 'replace'))
        self.help_active = True

    # -------------------------------------------------------------- rendering
    def render_initial(self):
        ctx = RenderCtx()
        ctx.all()
        self.render(ctx)

    def render(self, ctx):
        term = self.term
        buf = self.buf
        # effective rows given current message / prompt
        old_rows = self.screen_rows
        self.screen_rows = self.effective_rows()
        if self.screen_rows != old_rows:
            ctx.content_from = 'all'
            ctx.status = True
            ctx.message = True
        prev_offset = (buf.row_offset, buf.col_offset)
        self.ensure_visible(buf)
        if (buf.row_offset, buf.col_offset) != prev_offset:
            ctx.content_from = 'all'
            ctx.status = True
        screen_cursor = self._screen_cursor(buf)
        # nothing to do?
        if ctx.content_from is None and not ctx.status and not ctx.message:
            if self._last_cursor_screen == screen_cursor:
                self._first_render = False
                return
            # cursor-only move
            if screen_cursor is not None:
                term.write(('\x1b[%d;%dH' % (screen_cursor[1] + 1,
                                             screen_cursor[0] + 1)
                            ).encode())
                self._last_cursor_screen = screen_cursor
            self._first_render = False
            return
        term.write(b'\x1b[?25l')
        out = []
        if term.mode256:
            out.append('\x1b[39;0m\x1b[38;5;230m\x1b[48;5;235m')
        else:
            out.append('\x1b[39;0m')
        # ---- content rows
        if ctx.content_from is not None:
            start_screen = 0
            if ctx.content_from != 'all':
                start_screen = max(0, ctx.content_from - buf.row_offset)
            for srow in range(start_screen, self.screen_rows):
                out.append('\x1b[%dH' % (srow + 1))
                y = buf.row_offset + srow
                if self._first_render and self._show_welcome and \
                        y - buf.row_offset == self.screen_rows // 3:
                    out.append(self._welcome_row())
                elif y < len(buf.rows):
                    out.append(self._render_row(buf, y))
                else:
                    out.append(term.color_seq('tilde'))
                    out.append('~')
                out.append(term.reset_normal())
                out.append('\x1b[K')
        # ---- status bar
        if ctx.status:
            status = self._status_text(buf)
            status = _truncate_bytes(status, term.cols,
                                     '/workspace/src/screen.rs:209:25')
            out.append('\x1b[%dH' % (self.screen_rows + 1))
            out.append(term.reset_normal())
            out.append('\x1b[7m')
            out.append(status)
            out.append(term.reset_after_status())
        # ---- message / prompt
        msg_text, msg_alert = self._effective_message()
        if ctx.message and msg_text != '':
            shown = _truncate_bytes(msg_text, term.cols,
                                    '/workspace/src/screen.rs:238:33')
            out.append('\x1b[%dH' % (self.screen_rows + 2))
            if msg_alert:
                out.append(term.alert_seq())
            else:
                out.append(term.reset_normal())
            out.append(shown)
            out.append(term.reset_normal())
            out.append('\x1b[K')
        # ---- cursor
        if self.prompt is not None:
            out.append('\x1b[%d;%dH' % (screen_cursor[1] + 1,
                                        screen_cursor[0] + 1))
            out.append('\x1b[?25h')
            prow = self.term.rows
            pcol = self.prompt.label_len() + len(self.prompt.text) + 1
            out.append('\x1b[%d;%dH' % (prow, pcol))
        else:
            out.append('\x1b[%d;%dH' % (screen_cursor[1] + 1,
                                        screen_cursor[0] + 1))
            out.append('\x1b[?25h')
        term.write(''.join(out).encode('utf-8', 'replace'))
        self._last_cursor_screen = screen_cursor
        self._first_render = False

    def _screen_cursor(self, buf):
        rx = self.cursor_rx(buf)
        x = rx - buf.col_offset
        y = buf.cy - buf.row_offset
        if x < 0:
            x = 0
        if y < 0:
            y = 0
        return (x, y)

    def _effective_message(self):
        if self.prompt is not None:
            return self.prompt.message_text(), False
        return self.message, self.message_alert

    def _welcome_row(self):
        term = self.term
        cols = term.cols
        if cols < len(WELCOME) + 2:
            return term.reset_normal() + WELCOME[:cols]
        pad = (cols - 2 - len(WELCOME)) // 2
        if pad < 0:
            pad = 0
        return (term.color_seq('tilde') + '~' + term.reset_normal()
                + ' ' * pad + WELCOME)

    def _status_text(self, buf):
        name = buf.filename if buf.filename is not None else '[No Name]'
        left = '"%s" - %d/%d ' % (name, self.cur + 1, len(self.buffers))
        if buf.dirty:
            left += '(modified)'
        right = '%s %d/%d' % (buf.syntax.name, buf.cy + 1, len(buf.rows))
        if utf8_byte_len(left) + utf8_byte_len(right) <= self.term.cols:
            fill = self.term.cols - utf8_byte_len(left) - utf8_byte_len(right)
            return left + ' ' * fill + right
        return left

    def _render_row(self, buf, y):
        term = self.term
        row = buf.rows[y]
        hls = buf.row_highlights(y)
        # search matches
        match_cat = {}
        if self.prompt is not None and self.prompt.kind == 'search' and \
                self.prompt.text:
            query = self.prompt.text
            start = 0
            while True:
                idx = row.find(query, start)
                if idx == -1:
                    break
                cat = HL_MATCH_CURRENT if (y == buf.cy and idx == buf.cx) \
                    else HL_MATCH
                for k in range(idx, idx + len(query)):
                    match_cat[k] = cat
                start = idx + 1
        # build display cells: (char, category, display_start, width)
        cells = []
        rx = 0
        for j, ch in enumerate(row):
            cat = match_cat.get(j)
            if cat is None and hls is not None:
                cat = hls[j]
            if cat is None:
                cat = HL_NORMAL
            if ch == '\t':
                w = 8 - (rx % 8)
                for t in range(w):
                    cells.append((' ', cat, rx + t, 1))
                rx += w
            else:
                w = char_width(ch)
                cells.append((ch, cat, rx, w))
                rx += w
        offset = buf.col_offset
        cols = term.cols
        visible = []
        for ch, cat, start, w in cells:
            if w == 0:
                if offset <= start < offset + cols:
                    visible.append((ch, cat))
            elif start >= offset and start < offset + cols:
                visible.append((ch, cat))
        # group into runs
        out = []
        cur_cat = None
        run_text = []
        for ch, cat in visible:
            if cat != cur_cat:
                if run_text:
                    out.append(term.color_seq(cur_cat))
                    out.append(''.join(run_text))
                cur_cat = cat
                run_text = [ch]
            else:
                run_text.append(ch)
        if run_text:
            out.append(term.color_seq(cur_cat))
            out.append(''.join(run_text))
        return ''.join(out)


def _prev_word_target(text, cx):
    if cx <= 0:
        return 0
    cx -= 1
    if cx >= len(text):
        cx = len(text) - 1
        if cx < 0:
            return 0
    ch = text[cx]
    if is_word_char(ch):
        while cx > 0 and is_word_char(text[cx - 1]):
            cx -= 1
        return cx
    while cx >= 0:
        ch = text[cx]
        if is_word_char(ch):
            break
        if cx == 0:
            return 0
        cx -= 1
    while cx > 0 and is_word_char(text[cx - 1]):
        cx -= 1
    return cx


def _is_char_boundary(text, byte_index):
    data = text.encode('utf-8')
    if byte_index >= len(data):
        return byte_index == len(data)
    # a boundary if the byte at index is not a continuation byte
    return (data[byte_index] & 0xC0) != 0x80


def _truncate_bytes(text, width, location):
    data = text.encode('utf-8')
    if len(data) <= width:
        return text
    if not _is_char_boundary(text, width):
        # find the character containing byte `width`
        pos = 0
        for ch in text:
            ch_len = len(ch.encode('utf-8'))
            if pos < width < pos + ch_len or (pos == width):
                raise EditorPanic(
                    location,
                    'byte index %d is not a char boundary; it is inside '
                    "'%s' (bytes %d..%d) of `%s`"
                    % (width, ch, pos, pos + ch_len, text))
            pos += ch_len
        raise EditorPanic(
            location,
            'byte index %d is not a char boundary of `%s`' % (width, text))
    return data[:width].decode('utf-8')


# ----------------------------------------------------------------- terminal

class Terminal:
    def __init__(self):
        self.cols = 80
        self.rows = 24
        self.mode256 = False
        self._orig_attr = None
        self._in_alt = False

    # raw mode ------------------------------------------------------------
    def setup_raw(self):
        import termios
        import tty
        try:
            self._orig_attr = termios.tcgetattr(0)
        except OSError as exc:
            raise FatalError(format_os_error(exc))
        try:
            tty.setraw(0)
        except OSError as exc:
            raise FatalError(format_os_error(exc))

    def restore(self):
        import termios
        if self._orig_attr is not None:
            try:
                termios.tcsetattr(0, termios.TCSADRAIN, self._orig_attr)
            except OSError:
                pass
            self._orig_attr = None

    # size -------------------------------------------------------------------
    def query_size(self):
        cols, rows = self._ioctl_size()
        if cols > 0 and rows > 0:
            self.cols, self.rows = cols, rows
            return cols, rows
        # fall back to asking the terminal with a cursor-position query
        self._dsr_query()
        return self.cols, self.rows

    def query_size_soft(self):
        cols, rows = self._ioctl_size()
        if cols > 0 and rows > 0:
            return cols, rows
        return self.cols, self.rows

    def _ioctl_size(self):
        import fcntl
        import termios
        try:
            packed = fcntl.ioctl(1, termios.TIOCGWINSZ,
                                 struct.pack('HHHH', 0, 0, 0, 0))
            rows, cols, _x, _y = struct.unpack('HHHH', packed)
            return cols, rows
        except OSError:
            return 0, 0

    def _dsr_query(self):
        try:
            os.write(1, b'\x1b[9999C\x1b[9999B\x1b[6n')
        except OSError:
            pass
        data = bytearray()
        # read until 'R'
        while True:
            try:
                chunk = os.read(0, 1)
            except OSError:
                break
            if not chunk:
                break
            data.extend(chunk)
            if chunk == b'R':
                break
            if len(data) > 64:
                break
        m = re.search(rb'\[(\d+);(\d+)R', bytes(data))
        if m:
            self.rows = int(m.group(1))
            self.cols = int(m.group(2))

    # colors -----------------------------------------------------------------
    def detect_color_mode(self):
        self.mode256 = _detect_256color()

    def write(self, data):
        if isinstance(data, str):
            data = data.encode('utf-8', 'replace')
        view = memoryview(data)
        while view:
            try:
                written = os.write(1, view)
            except OSError:
                return
            view = view[written:]

    def enter_alt_screen(self):
        self.write(b'\x1b[?1049h')
        self._in_alt = True

    def leave_alt_screen(self):
        if self._in_alt:
            self.write(b'\x1b[?1049l\x1b[H')
            self._in_alt = False

    # color sequences ---------------------------------------------------------
    def color_seq(self, cat):
        if self.mode256:
            fg = {
                HL_NORMAL: 230, HL_KEYWORD: 109, HL_CONTROL: 167,
                HL_TYPE: 208, HL_STRING: 142, HL_COMMENT: 246,
                HL_LITERAL: 175, HL_NAME: 214, HL_SPECIAL: 108,
                'tilde': 241,
            }.get(cat)
            if cat == HL_MATCH:
                return '\x1b[39;0m\x1b[38;5;235m\x1b[48;5;214m'
            if cat == HL_MATCH_CURRENT:
                return '\x1b[39;0m\x1b[38;5;235m\x1b[48;5;166m'
            if fg is None:
                return ''
            if cat == HL_NORMAL:
                return '\x1b[39;0m\x1b[38;5;230m\x1b[48;5;235m'
            return '\x1b[38;5;%dm' % fg
        codes = {
            HL_KEYWORD: 94, HL_CONTROL: 91, HL_TYPE: 33, HL_STRING: 32,
            HL_COMMENT: 90, HL_LITERAL: 95, HL_NAME: 93, HL_SPECIAL: 96,
            'tilde': 37,
        }
        if cat == HL_MATCH:
            return '\x1b[30m\x1b[103m'
        if cat == HL_MATCH_CURRENT:
            return '\x1b[30m\x1b[107m'
        if cat == HL_NORMAL or cat is None:
            return '\x1b[39;0m'
        return '\x1b[%dm' % codes.get(cat, 39)

    def reset_normal(self):
        if self.mode256:
            return '\x1b[39;0m\x1b[38;5;230m\x1b[48;5;235m'
        return '\x1b[39;0m'

    def reset_after_status(self):
        return self.reset_normal()

    def alert_seq(self):
        if self.mode256:
            return '\x1b[38;5;230m\x1b[48;5;124m'
        return '\x1b[97m\x1b[41m'


