    rows = []
    start = 0
    n = len(text)
    while start < n:
        idx = text.find('\n', start)
        if idx == -1:
            rows.append(text[start:])
            break
        line = text[start:idx]
        if line.endswith('\r'):
            line = line[:-1]
        rows.append(line)
        start = idx + 1
    return rows


